// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _test(uint256 sum1, uint256 sum2) internal {
        vm.assume(sum1 != sum2);
        try c.SetMinSum(sum1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted = false;
        try c.SetMinSum(sum2) { } catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_test(uint256 sum1, uint256 sum2) public {
        _test(sum1, sum2);
    }

    receive() external payable {}
}
